def j(k):
    try: return json.load(open(os.path.join(BASE, F[k])))
    except Exception: return None
def _clean(o):   # NaN/Inf -> null so the browser's JSON parser never fails (fix 2026-10-29)
    import math
    if isinstance(o, float): return o if math.isfinite(o) else None
    if isinstance(o, dict): return {k: _clean(v) for k, v in o.items()}
    if isinstance(o, (list, tuple)): return [_clean(v) for v in o]
    return o
def state():
    S = {k: j(k) for k in F}; q = S.pop("queue") or {}
    try:   # tfo_board_live_20261031: card is a run snapshot; drop picks/proposals the live book has closed/cancelled (stale ABBV-1521 board)
        _dead = {p.get("id") for s in ((S.get("book") or {}).get("seats") or {}).values() for p in (s.get("closed") or [])}
        _c = S.get("card") or {}
        if _dead and _c:
            _c["proposals"] = [p for p in (_c.get("proposals") or []) if p.get("id") not in _dead]
            if isinstance(_c.get("head_of_desk"), dict): _c["head_of_desk"]["top_picks"] = [p for p in (_c["head_of_desk"].get("top_picks") or []) if p.get("id") not in _dead]
    except Exception: pass
    try:
        U = [json.loads(l) for l in open(os.path.join(BASE, "state/veteran_desk/model_usage.jsonl")).read().splitlines()[-200:]]
    except Exception: U = []
    S["model_usage"] = dict(calls=len(U), ok=sum(1 for u in U if u.get("ok")), timeouts=sum(1 for u in U if u.get("timeout")), rate_limited=sum(1 for u in U if u.get("rate_limited")),
        by_model={m: sum(1 for u in U if u.get("model") == m) for m in sorted({u.get("model") for u in U})}, last=U[-8:])
    S["queue"] = [e for e in (q.get("entries") or {}).values() if e.get("book") == "veteran"][-30:]
    names = {}
    sd = os.path.join(BASE, "veteran_desk", "seats")
    for f in os.listdir(sd):
        try: c = json.load(open(os.path.join(sd, f))); names[c["seat"]] = dict(name=c.get("trader_name"), role=c["role"], engine=c["engine"])
        except Exception: pass
    for _k, _lbl in (("trend", "Dex Romano · Trend"), ("price_action", "Dex Romano · Price Action")):   # dexlabel 2026-10-30: display only (two seats, one trader)
        if _k in names: names[_k]["name"] = _lbl
    S["names"] = names; S["rank_hidden"] = list(RANK_HIDDEN)
    try:   # daily leaderboard (Brett 20:13 WITA): live standings computed read-only from the book + opening marks; last awards from the jsonl
        import sys; BASE in sys.path or sys.path.insert(0, BASE); from veteran_desk import leaderboard as LB
        lb = LB.standings(D=S["book"]) if S.get("book") else None
        if lb:
            lb["awards"] = LB._awards()[-8:]; lb["week"] = LB.week_so_far()
            try:   # dashaudit 2026-10-30: week table = closed daily cutoffs + the live day since 06:00 WITA (was cutoffs only -> disagreed with week-to-date)
                wk = {r["seat"]: r["week_pnl_aud"] for r in lb["week"].get("rows", [])}
                for r in lb.get("rows", []): wk[r["seat"]] = round(wk.get(r["seat"], 0.0) + float(r.get("day_pnl_aud") or 0), 2)
                lb["week"]["rows"] = sorted(({"seat": k, "week_pnl_aud": v} for k, v in wk.items()), key=lambda r: (-r["week_pnl_aud"], r["seat"])); lb["week"]["incl_live_day"] = True
            except Exception: pass
        S["leaderboard"] = lb
    except Exception as x: S["leaderboard"] = dict(error="%s: %s" % (type(x).__name__, str(x)[:160]))
    try:   # tfo_review_20261030: per-seat learning stats (win rate, avg R, giveback, slippage, fee drag)
        from veteran_desk import lesson_loop as LL, book as BK_; S["seat_stats"] = LL.read_stats(BK_._state_dir())
    except Exception as x: S["seat_stats"] = dict(error=str(x)[:160], seats={})
    try:   # learning loop card (Brett 2026-10-28 20:26 WITA): read-only
        from veteran_desk import learning as LRN; S["learning"] = LRN.card()
    except Exception as x: S["learning"] = dict(error="%s: %s" % (type(x).__name__, str(x)[:160]))
    return S
